CREATE TABLE exam (exam_id INT UNSIGNED NOT NULL AUTO_INCREMENT,offering_id INT UNSIGNED NOT NULL,exam_name VARCHAR(100) NOT NULL,exam_date DATE NOT NULL,max_marks DECIMAL(5,2) NOT NULL,registration_open TINYINT(1) NOT NULL DEFAULT 1,results_published TINYINT(1) NOT NULL DEFAULT 0,CONSTRAINT pk_exam PRIMARY KEY(exam_id),CONSTRAINT ck_exam_marks CHECK(max_marks>0));
CREATE TABLE exam_hall (exam_hall_id INT UNSIGNED NOT NULL AUTO_INCREMENT,hall_name VARCHAR(60) NOT NULL,capacity SMALLINT UNSIGNED NOT NULL,CONSTRAINT pk_exam_hall PRIMARY KEY(exam_hall_id),CONSTRAINT uq_exam_hall_name UNIQUE(hall_name),CONSTRAINT ck_exam_hall_capacity CHECK(capacity>0));
CREATE TABLE exam_registration (exam_registration_id INT UNSIGNED NOT NULL AUTO_INCREMENT,exam_id INT UNSIGNED NOT NULL,enrollment_id INT UNSIGNED NOT NULL,exam_hall_id INT UNSIGNED NULL,registered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_exam_registration PRIMARY KEY(exam_registration_id),CONSTRAINT uq_exam_registration UNIQUE(exam_id,enrollment_id),CONSTRAINT fk_exam_registration_exam FOREIGN KEY(exam_id) REFERENCES exam(exam_id),CONSTRAINT fk_exam_registration_hall FOREIGN KEY(exam_hall_id) REFERENCES exam_hall(exam_hall_id));
CREATE TABLE grade_scale (grade_scale_id INT UNSIGNED NOT NULL AUTO_INCREMENT,grade VARCHAR(2) NOT NULL,minimum_percent DECIMAL(5,2) NOT NULL,grade_point DECIMAL(4,2) NOT NULL,CONSTRAINT pk_grade_scale PRIMARY KEY(grade_scale_id),CONSTRAINT uq_grade_scale_grade UNIQUE(grade),CONSTRAINT ck_grade_scale_percent CHECK(minimum_percent BETWEEN 0 AND 100));
CREATE TABLE marks (marks_id INT UNSIGNED NOT NULL AUTO_INCREMENT,exam_registration_id INT UNSIGNED NOT NULL,marks_obtained DECIMAL(5,2) NOT NULL,grade_scale_id INT UNSIGNED NULL,entered_by INT UNSIGNED NULL,entered_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_marks PRIMARY KEY(marks_id),CONSTRAINT uq_marks_registration UNIQUE(exam_registration_id),CONSTRAINT fk_marks_registration FOREIGN KEY(exam_registration_id) REFERENCES exam_registration(exam_registration_id),CONSTRAINT fk_marks_grade FOREIGN KEY(grade_scale_id) REFERENCES grade_scale(grade_scale_id));
CREATE TABLE marks_audit (marks_audit_id INT UNSIGNED NOT NULL AUTO_INCREMENT,marks_id INT UNSIGNED NOT NULL,old_marks DECIMAL(5,2) NULL,new_marks DECIMAL(5,2) NOT NULL,changed_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_marks_audit PRIMARY KEY(marks_audit_id),CONSTRAINT fk_marks_audit_marks FOREIGN KEY(marks_id) REFERENCES marks(marks_id));
CREATE TABLE result_summary (result_summary_id INT UNSIGNED NOT NULL AUTO_INCREMENT, student_id INT UNSIGNED NOT NULL, semester_id INT UNSIGNED NOT NULL, sgpa DECIMAL(4,2) NOT NULL, cgpa DECIMAL(4,2) NOT NULL, published_at TIMESTAMP NOT NULL DEFAULT  CURRENT_TIMESTAMP, CONSTRAINT pk_result_summary PRIMARY KEY (result_summary_id), CONSTRAINT uq_result_summary UNIQUE (student_id, semester_id));
CREATE TABLE revaluation_request (revaluation_request_id INT UNSIGNED NOT NULL AUTO_INCREMENT,marks_id INT UNSIGNED NOT NULL,reason VARCHAR(500) NOT NULL,status ENUM('PENDING','APPROVED','REJECTED') NOT NULL DEFAULT 'PENDING',requested_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT pk_revaluation_request PRIMARY KEY(revaluation_request_id),CONSTRAINT fk_revaluation_marks FOREIGN KEY(marks_id) REFERENCES marks(marks_id));
